#!/usr/bin/env python3
"""Compile the actual Split MDX C++20 fence and compare literal partitions."""
from pathlib import Path
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile

HARNESS = '\n#include <bit>\n#include <chrono>\n#include <climits>\n#include <cstdlib>\n#include <iostream>\n#include <numeric>\n#include <random>\n#include <string>\nusing Mask=std::uint32_t;\nstd::uint64_t checks=0,calls=0,graphs=0,sorted_cases=0,ordered_cases=0;\nstd::uint64_t assignments=0,random_cases=0,parallel_cases=0,large_cases=0,checksum=0;\nvoid require(bool yes,const char* reason) {\n    ++checks;if(!yes){std::cerr<<"FAIL "<<reason<<\'\\n\';std::exit(1);}\n}\nstd::vector<unsigned char> connected_masks(const std::vector<Mask>& adj) {\n    const unsigned limit=1u<<adj.size();std::vector<unsigned char> good(limit,0);\n    for(unsigned mask=1;mask<limit;++mask){\n        unsigned seen=0,todo=mask&(~mask+1u);\n        while(todo){unsigned bit=todo&(~todo+1u);todo^=bit;\n            if(seen&bit)continue;\n            seen|=bit;\n            todo|=adj[std::countr_zero(bit)]&mask&~seen;\n        }\n        good[mask]=seen==mask;\n    }\n    return good;\n}\nstruct Oracle {\n    bool feasible[9][9]{};\n    bool small_connected[9][9]{};\n    std::vector<unsigned char> good;\n};\n// Literal ordered partitions: every vertex gets one of three labels. The\n// connectivity checks below use only graph searches on the assigned masks.\nOracle oracle(const std::vector<Mask>& adj) {\n    Oracle out;out.good=connected_masks(adj);\n    const unsigned full=(1u<<adj.size())-1;\n    for(unsigned aa=1;aa<full;++aa){\n        const unsigned remaining=full^aa;\n        for(unsigned bb=remaining;bb;bb=(bb-1)&remaining){\n            const unsigned cc=remaining^bb;if(!cc)continue;++assignments;\n            const int a=std::popcount(aa),b=std::popcount(bb);\n            if(out.good[aa]+out.good[bb]+out.good[cc]>=2)out.feasible[a][b]=true;\n            if(out.good[aa]&&out.good[bb])out.small_connected[a][b]=true;\n        }\n    }\n    return out;\n}\nvoid verify_small(int n,std::array<int,3> sizes,const std::vector<int>& p,\n                  const std::vector<int>& q,const Oracle& truth,bool expected,bool wrapper=false){\n    const auto answer=wrapper?find_split(n,sizes[0],sizes[1],sizes[2],p,q):\n        partition_three_two_connected(n,sizes,p,q);++calls;\n    require(answer.size()==static_cast<std::size_t>(n),"answer has n labels");\n    const bool zero=std::all_of(answer.begin(),answer.end(),[](int x){return x==0;});\n    require(!zero==expected,"existence agrees with literal three-way partition oracle");\n    for(int x:answer)checksum=checksum*1000003u+static_cast<unsigned>(x+3);\n    if(zero)return;\n    std::array<Mask,3> groups{};std::array<int,3> count{};\n    for(int v=0;v<n;++v){\n        require(1<=answer[v]&&answer[v]<=3,"success contains only labels 1,2,3");\n        groups[answer[v]-1]|=Mask{1}<<v;++count[answer[v]-1];\n    }\n    require(count==sizes,"all original ordered sizes are exact");\n    require(truth.good[groups[0]]+truth.good[groups[1]]+truth.good[groups[2]]>=2,\n            "at least two induced groups are connected");\n    std::array<std::pair<int,int>,3> sorted{};\n    for(int i=0;i<3;++i)sorted[i]={sizes[i],i};\n    std::sort(sorted.begin(),sorted.end());\n    require(truth.good[groups[sorted[0].second]]&&truth.good[groups[sorted[1].second]],\n            "the two sorted-smallest label groups are individually connected");\n}\nvoid exhaustive(){\n    for(int n=3;n<=6;++n){\n        std::vector<std::pair<int,int>> edges;\n        for(int u=0;u<n;++u)for(int v=u+1;v<n;++v)edges.push_back({u,v});\n        for(unsigned code=0;code<(1u<<edges.size());++code){\n            std::vector<Mask> adj(n,0);std::vector<int> p,q;\n            for(std::size_t e=0;e<edges.size();++e)if(code>>e&1u){\n                const auto [u,v]=edges[e];p.push_back(u);q.push_back(v);adj[u]|=Mask{1}<<v;adj[v]|=Mask{1}<<u;\n            }\n            if(!connected_masks(adj).back())continue;\n            ++graphs;\n            const auto truth=oracle(adj);\n            for(int a=1;a<n-1;++a)for(int b=1;b<n-a;++b){\n                const int c=n-a-b;std::array<int,3> sizes{a,b,c},sorted=sizes;\n                std::sort(sorted.begin(),sorted.end());\n                require(truth.feasible[a][b]==truth.small_connected[sorted[0]][sorted[1]],\n                        "two smallest connected equivalence holds in the independent full oracle");\n                verify_small(n,sizes,p,q,truth,truth.feasible[a][b]);++ordered_cases;\n                if(a<=b&&b<=c)++sorted_cases;\n            }\n        }\n    }\n    require(graphs==27474,"all connected labeled simple graphs of orders three to six");\n    require(sorted_cases==81610,"all sorted positive size triples from the research corpus");\n    require(ordered_cases==271526,"all ordered triples, including every distinct size permutation");\n}\nvoid randomized(){\n    std::mt19937 rng(0x51717);\n    for(int scenario=0;scenario<1200;++scenario){\n        const int n=3+static_cast<int>(rng()%6);std::vector<Mask> adj(n,0);\n        for(int v=1;v<n;++v){const int u=static_cast<int>(rng()%v);adj[u]|=Mask{1}<<v;adj[v]|=Mask{1}<<u;}\n        for(int u=0;u<n;++u)for(int v=u+1;v<n;++v)if(rng()%3==0){adj[u]|=Mask{1}<<v;adj[v]|=Mask{1}<<u;}\n        std::vector<int> rename(n);std::iota(rename.begin(),rename.end(),0);std::shuffle(rename.begin(),rename.end(),rng);\n        std::vector<std::pair<int,int>> edges;std::vector<Mask> renamed(n,0);\n        for(int u=0;u<n;++u)for(int v=u+1;v<n;++v)if(adj[u]>>v&1u){\n            int x=rename[u],y=rename[v];if(rng()&1u)std::swap(x,y);edges.push_back({x,y});\n            renamed[x]|=Mask{1}<<y;renamed[y]|=Mask{1}<<x;\n        }\n        std::shuffle(edges.begin(),edges.end(),rng);std::vector<int> p,q;\n        for(auto [u,v]:edges){p.push_back(u);q.push_back(v);}\n        const auto truth=oracle(renamed);const int a=1+static_cast<int>(rng()%(n-2));\n        const int b=1+static_cast<int>(rng()%(n-a-1));std::array<int,3> sizes{a,b,n-a-b};\n        verify_small(n,sizes,p,q,truth,truth.feasible[a][b],scenario<100);++random_cases;\n        std::vector<int> pp,qq;\n        for(std::size_t e=0;e<p.size();++e)for(unsigned copy=1+rng()%4;copy;--copy){\n            if(rng()&1u){pp.push_back(p[e]);qq.push_back(q[e]);}else{pp.push_back(q[e]);qq.push_back(p[e]);}\n        }\n        verify_small(n,sizes,pp,qq,truth,truth.feasible[a][b]);++parallel_cases;\n    }\n}\nvoid explicit_lowlink(){\n    // Without the edge to strict ancestor 0, all components of G-1 have\n    // fewer than three vertices. The edge to pivot 1 alone is insufficient.\n    std::vector<int> p{0,1,2,1,4,1,6,1,1},q{1,2,3,4,5,6,7,8,3};\n    auto run=[&](bool expected){std::vector<Mask> adj(9,0);\n        for(std::size_t e=0;e<p.size();++e){adj[p[e]]|=Mask{1}<<q[e];adj[q[e]]|=Mask{1}<<p[e];}\n        // Order nine uses the literal mask oracle separately from size tables.\n        const auto good=connected_masks(adj);bool found=false;const unsigned full=511;\n        for(unsigned aa=1;aa<full;++aa)if(std::popcount(aa)==3)\n            for(unsigned bb=full^aa;bb;bb=(bb-1)&(full^aa))if(std::popcount(bb)==3){\n                ++assignments;const auto cc=full^aa^bb;\n                if(good[aa]+good[bb]+good[cc]>=2)found=true;\n            }\n        require(found==expected,"strict-ancestor witness oracle");\n        Oracle truth;truth.good=good;verify_small(9,{3,3,3},p,q,truth,expected);\n    };\n    run(false);p.push_back(0);q.push_back(3);run(true);\n    const std::vector<int> samplep{0,0,0,0,0,0,1,3,4,5},sampleq{1,2,3,4,6,8,7,7,5,6};\n    std::vector<Mask> adj(9,0);\n    for(std::size_t e=0;e<samplep.size();++e){adj[samplep[e]]|=Mask{1}<<sampleq[e];adj[sampleq[e]]|=Mask{1}<<samplep[e];}\n    Oracle truth;truth.good=connected_masks(adj);verify_small(9,{4,2,3},samplep,sampleq,truth,true,true);\n}\nvoid verify_large(int n,std::array<int,3> sizes,const std::vector<int>& p,const std::vector<int>& q,bool expected){\n    const auto answer=partition_three_two_connected(n,sizes,p,q);++calls;++large_cases;\n    require(answer.size()==static_cast<std::size_t>(n),"large output length");\n    const bool zero=std::all_of(answer.begin(),answer.end(),[](int x){return x==0;});\n    require(!zero==expected,"large known family existence");\n    for(int x:answer)checksum=checksum*1000003u+static_cast<unsigned>(x+3);\n    if(zero)return;\n    std::vector<std::vector<int>> adj(n);for(std::size_t e=0;e<p.size();++e){adj[p[e]].push_back(q[e]);adj[q[e]].push_back(p[e]);}\n    std::array<int,3> counts{},components{};std::vector<unsigned char> seen(n,0);\n    for(int v=0;v<n;++v){require(1<=answer[v]&&answer[v]<=3,"large label range");++counts[answer[v]-1];}\n    require(counts==sizes,"large original size order");\n    for(int v=0;v<n;++v)if(!seen[v]){\n        ++components[answer[v]-1];std::vector<int> todo{v};seen[v]=1;\n        for(std::size_t at=0;at<todo.size();++at)for(int u:adj[todo[at]])\n            if(!seen[u]&&answer[u]==answer[v]){seen[u]=1;todo.push_back(u);}\n    }\n    require((components[0]==1)+(components[1]==1)+(components[2]==1)>=2,"large induced connectivity");\n    std::array<std::pair<int,int>,3> sorted{};for(int i=0;i<3;++i)sorted[i]={sizes[i],i};\n    std::sort(sorted.begin(),sorted.end());require(components[sorted[0].second]==1&&components[sorted[1].second]==1,"large smallest groups connected");\n}\nvoid large(){\n    const int n=100000;std::vector<int> p,q;\n    for(int i=1;i<n;++i){p.push_back(i-1);q.push_back(i);}\n    std::array<int,3> sizes{33333,33333,33334};\n    do{verify_large(n,sizes,p,q,true);}while(std::next_permutation(sizes.begin(),sizes.end()));\n    p.push_back(0);q.push_back(n-1);verify_large(n,{1,2,n-3},p,q,true);\n    p.clear();q.clear();for(int i=1;i<n;++i){p.push_back(0);q.push_back(i);}\n    verify_large(n,{33333,33333,33334},p,q,false);\n    verify_large(n,{n-2,1,1},p,q,true);verify_large(n,{1,n-2,1},p,q,true);verify_large(n,{1,1,n-2},p,q,true);\n    p.clear();q.clear();for(int i=1;i<n;++i){p.push_back(i-1);q.push_back(i);}\n    for(int i=2;i<n;++i){p.push_back(i-2);q.push_back(i);}\n    p.push_back(0);q.push_back(n-1);p.push_back(0);q.push_back(n-2);p.push_back(1);q.push_back(n-1);\n    require(p.size()==200000,"original maximum edge count is tested");\n    verify_large(n,{33334,33333,33333},p,q,true);\n    p.clear();q.clear();for(int i=1;i<n;++i)for(int copy=0;copy<2;++copy){p.push_back(i-1);q.push_back(i);}\n    p.push_back(0);q.push_back(1);p.push_back(0);q.push_back(1);\n    verify_large(n,{33333,33334,33333},p,q,true);\n    p.clear();q.clear();for(int i=1;i<100003;++i){p.push_back(i-1);q.push_back(i);}\n    verify_large(100003,{1,50000,50002},p,q,true);\n}\nstd::uint64_t invalid_cases=0;\nvoid rejects(int n,std::array<int,3> sizes,std::vector<int> p={},std::vector<int> q={}){\n    bool rejected=false;try{(void)partition_three_two_connected(n,sizes,p,q);}catch(const std::invalid_argument&){rejected=true;}\n    require(rejected,"invalid input throws invalid_argument");++invalid_cases;\n}\nint main(){\n    const auto begin=std::chrono::steady_clock::now();exhaustive();randomized();explicit_lowlink();large();\n    rejects(0,{1,1,1});rejects(-1,{1,1,1});rejects(2,{1,1,0});rejects(3,{0,1,2});\n    rejects(3,{-1,1,3});rejects(3,{1,1,2});rejects(INT_MAX,{INT_MAX,INT_MAX,INT_MAX});\n    rejects(3,{INT_MIN,INT_MAX,4});rejects(3,{1,1,1},{0,1},{1});\n    rejects(3,{1,1,1},{-1,1},{1,2});rejects(3,{1,1,1},{0,1},{1,3});\n    rejects(3,{1,1,1},{INT_MAX,1},{1,2});rejects(3,{1,1,1},{INT_MIN,1},{1,2});\n    rejects(3,{1,1,1},{0,1,0},{1,2,0});rejects(3,{1,1,1});rejects(4,{1,1,2},{0,0},{1,1});\n    const auto after_invalid=find_split(3,1,1,1,{0,1},{1,2});require(after_invalid.size()==3&&after_invalid[0]!=0,"calls remain independent after rejection");\n    std::cout<<"{\\"checks\\":"<<checks<<",\\"apiCalls\\":"<<calls<<",\\"connectedGraphs\\":"<<graphs\n             <<",\\"sortedSizeCases\\":"<<sorted_cases<<",\\"orderedSizeCases\\":"<<ordered_cases\n             <<",\\"literalPartitions\\":"<<assignments<<",\\"randomGraphCases\\":"<<random_cases\n             <<",\\"parallelEdgeCases\\":"<<parallel_cases<<",\\"largeCases\\":"<<large_cases\n             <<",\\"invalidCases\\":"<<invalid_cases<<",\\"checksum\\":\\""<<checksum<<"\\",\\"seconds\\":"\n             <<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()<<"}\\n";\n}\n'

args = [arg for arg in sys.argv[1:] if arg != '--sanitize']
article = Path(args[0]) if args else Path(__file__).resolve().parents[1] / 'src/content/docs/techniques/dfs-lowlink-three-size-two-connected-partition.mdx'
blocks = re.findall(r'^```cpp\s*\n(.*?)^```\s*$', article.read_text(), re.M | re.S)
if len(blocks) != 1:
    raise RuntimeError('expected exactly one complete visible C++20 fence')
with tempfile.TemporaryDirectory(prefix='flowchartcp-split-') as directory:
    source = Path(directory)/'check.cpp'
    binary = Path(directory)/'check'
    source.write_text(blocks[0]+'\n'+HARNESS)
    flags = ['-std=c++20','-O2','-Wall','-Wextra','-Werror']
    environment = os.environ.copy()
    if '--sanitize' in sys.argv:
        flags += ['-O1','-g','-fsanitize=address,undefined','-fno-omit-frame-pointer']
        environment['ASAN_OPTIONS'] = 'detect_leaks=0:halt_on_error=1'
        environment['UBSAN_OPTIONS'] = 'halt_on_error=1'
    compiler = environment.get('CXX') or shutil.which('g++') or shutil.which('clang++') or 'c++'
    subprocess.run([compiler,*flags,str(source),'-o',str(binary)],check=True,timeout=120)
    try:
        import resource
        def limit_stack():
            _,hard=resource.getrlimit(resource.RLIMIT_STACK)
            resource.setrlimit(resource.RLIMIT_STACK,(1048576,hard))
    except ImportError:
        limit_stack=None
    timer=Path('/usr/bin/time')
    command=[str(timer),'-f','peak_rss_kib=%M',str(binary)] if timer.exists() and sys.platform.startswith('linux') else [str(binary)]
    run=subprocess.run(command,check=True,text=True,capture_output=True,env=environment,timeout=240,preexec_fn=limit_stack)
    report=json.loads(run.stdout)
    match=re.search(r'^peak_rss_kib=(\d+)$',run.stderr,re.M)
    if match:report['peakRSSKiB']=int(match[1])
    report.update(article=str(article),sanitized='--sanitize' in sys.argv,stackLimitBytes=1048576 if limit_stack else None)
    print(json.dumps(report,ensure_ascii=False,indent=2))
